import {C,api,boot,changed,flush,loginHTML,modeHTML,syncHTML,teacherHTML} from './v5-client.js';
import {musicToggle,musicVolume,musicControls,icon} from './v5-media.js';
import {stops, chartedMap, scene, journalData, journalMarkup, pairingMarkup, bridgeMarkup} from './journey.js';
import {CONFIG} from './config.js';
import {stages,quiz,evaluation,activityMeta,missions} from './content.js';
import {uuid,esc,sequence,normalize,unlocked,newState,evaluationCSV,csvCell} from './core.js';
let S=newState();
let labBaseline=null;
let route=location.hash.slice(1)||'beranda',tab='baca',lab={start:5,step:3,count:5,shown:3,guess:false,prediction:'',reason:'',proved:false},labTimer=null,activeMission=null,evalReview=false,teacherData=null,backend={available:false,email:false},pendingStart=null;
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const iconKoma='<img src="assets/koma.svg" class="koma" alt="Si KOMA, robot penjelajah">';
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const nums=(arr,step)=>`<div class="numbers">${arr.map((n,i)=>`${i&&step!==undefined?`<span class="change">${step>0?'+':''}${step}</span>`:''}<span class="num ${i===arr.length-1?'new':''}">${esc(n)}</span>`).join('')}</div>`;
const textField=(name,label,placeholder='',kind='textarea',required=true)=>`<label for="${name}">${label}</label>${kind==='textarea'?`<textarea id="${name}" name="${name}" maxlength="2000" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(draft()[name]||'')}</textarea>`:`<input id="${name}" name="${name}" ${required?'required':''} type="${kind}" ${kind==='number'?'min="0" max="100"':''} maxlength="200" placeholder="${esc(placeholder)}" value="${esc(draft()[name]||'')}">`}`;
function draft(){return S.drafts[route]||{};}
let teachKey='',classRows=[],classFilter='',activeServerReport=null;
const downComplete=d=>['down1','down2','down4','down5','downReason'].every(k=>String(d?.[k]??'').trim());
function needsDecrease(s){const a=s.records.a2;return a&&!downComplete(a.revisions?.at(-1)?.data||a.initial?.data);}
function save(){if(C.role==='student'){S.lastRoute=route;changed(S);}return true;}
function recordSync(){save();}
function clearTeacher(){}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',5000);}
function mark(id){if(!S.done.includes(id))S.done.push(id);save();}
function next(id){const i=stages.findIndex(x=>x.id===id);return stages[i+1]?.id||'beranda';}
function go(id){if(labTimer){clearInterval(labTimer);labTimer=null;}activeMission=null;location.hash=id;if(route===id)render();}
function showModal(html){dialog.innerHTML=`<button class="close-dialog" aria-label="Tutup" data-action="close">×</button>${html}`;if(!dialog.open)dialog.showModal();}
function ensureStudent(){return C.role==='student';}
function head(title,sub,pill='KELAS IV · FASE B'){return `<div class="page-head"><div><div class="eyebrow">PULAU POLA / ${esc(route==='beranda'?'SELAMAT DATANG':title)}</div><h1>${title}</h1><p class="muted">${sub}</p></div><span class="pill">${pill}</span></div>`;}
function iconForNav(id){return icon(id);}
function navLink(id,title,icon){const active=route===id||(id==='aktivitas'&&/^a[1-4]$/.test(route));return `<a href="#${id}" class="nav-link ${active?'active':''}" ${active?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${iconForNav(id)}</span>${title}</a>`;}
function render(){
 route=location.hash.slice(1).replace(/^\//,'')||'beranda';
 if(!C.role){root.innerHTML=loginHTML(route==='guru');return;}
 if(C.role==='teacher'){root.innerHTML=teacherHTML();return;}
 if(route==='guru'){root.innerHTML='<main id="main" class="mode-screen"><h1>Ruang Guru</h1><p>Keluar dari akun siswa dahulu untuk masuk sebagai guru.</p><button class="btn" data-v5="logout">Keluar dari akun siswa</button><p><a href="#beranda">Kembali belajar</a></p></main>';return;}
 if(!S.mode){root.innerHTML=modeHTML();return;}

 if(route==='guru'&&(location.hash.slice(1)||'beranda')!=='guru')clearTeacher();
 document.body.classList.toggle('no-motion',!S.settings.motion);
 root.innerHTML=`<aside class="sidebar" aria-label="Navigasi utama"><a class="brand" href="#beranda"><img src="assets/koma.svg" alt=""><span><strong>KOMATIK</strong><small>Temukan pola. Ceritakan caramu.</small></span></a><div class="nav-label">RUANG BELAJAR</div><nav>${navLink('beranda','Beranda','⌂')}${navLink('materi','Materi','▤')}${navLink('aktivitas','Aktivitas','◈')}${navLink('kuis','Kuis','☆')}${navLink('game','Games','⚑')}${navLink('evaluasi','Evaluasi','✎')}${navLink('lab','Laboratorium Pola','lab')}${navLink('profil','Profil Developer','◉')}</nav><div class="sidebar-bottom"><strong>Pelan-pelan juga boleh.</strong><p>Yang penting, ceritakan alasan di balik jawabanmu.</p>${button('Cara menggunakan','help','soft small')}<a href="#guru" class="micro" style="display:block;margin-top:10px">Ruang guru</a></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Buka menu">☰</button><span>Matematika interaktif & komputasional</span><div class="top-actions"><button class="icon-btn" data-action="settings" aria-label="Pengaturan aksesibilitas">⚙</button><div class="user-chip"><span class="avatar">${S.student?'IV':'K'}</span><span><strong>${esc(S.student?.name||'Penjelajah baru')}</strong><small style="display:block">${esc(S.student?.className||'Siap belajar hari ini?')}</small></span><button class="icon-btn" data-action="session" aria-label="Kelola sesi siswa">⋯</button></div></div></header><main id="main" tabindex="-1">${page()}</main></div>`;
 document.querySelector('main').dataset.page=route;
 if(route==='lab'||route==='materi'&&tab==='lab')renderLab();
 document.querySelector('#main').insertAdjacentHTML('beforeend',syncHTML());document.querySelector('.top-actions').insertAdjacentHTML('afterbegin',musicControls());
 if(route==='game'&&document.querySelector('.island-map'))drawPlayer();
}
function page(){
 if(route==='lab')return head('Laboratorium Pola','Coba bilangan awal dan aturan berbeda. Laboratorium selalu tersedia.')+laboratory();

 if((/^a[1-4]$/.test(route)||route==='kuis'||route==='game')&&!C.settings.activities)return head('Aktivitas sedang ditutup guru','Progresmu tetap tersimpan. Kamu dapat membaca Materi atau mencoba Laboratorium Pola.');
 if(route==='evaluasi'&&!C.settings.evaluation&&!S.evaluation.submission)return head('Evaluasi belum dibuka','Tunggu petunjuk gurumu. Draf yang sudah tersimpan tetap tersedia.');
 if(stages.some(x=>x.id===route)&&!unlocked(route,S,stages,CONFIG.sequential))return locked();
 if(route==='beranda')return home();if(route==='materi')return material();if(route==='aktivitas')return activities();if(/^a[1-4]$/.test(route))return activity(Number(route[1])-1);if(route==='kuis')return quizPage();if(route==='game')return game();if(route==='evaluasi')return evaluationPage();if(route==='profil')return profile();return `${head('Halaman tidak ditemukan','Mari kembali ke peta perjalanan.')}<a class="btn" href="#beranda">Ke beranda</a>`;
}
function locked(){const first=stages.find(x=>!S.done.includes(x.id));return `${head('Satu langkah demi satu langkah','Selesaikan tahap sebelumnya untuk membuka tujuan ini.')}<div class="guide">${iconKoma}<div><strong>Selesaikan ${first.label} · ${first.name} terlebih dahulu.</strong><p>Kamu tidak harus selalu benar. Simpan jawaban, periksa, lalu lanjutkan.</p></div></div><p></p><a class="btn" href="#${first.id}">Buka ${first.name} →</a>`;}
function stageCard(st,i){const done=S.done.includes(st.id),open=unlocked(st.id,S,stages,CONFIG.sequential);return `<a class="stage-card ${open?'':'locked'}" href="#${st.id}"><span class="tile-icon ${st.color}">${icon(st.id)}</span><span class="card-arrow">${done?'✓':open?'↗':'○'}</span><small>${String(i+1).padStart(2,'0')} / ${st.label.toUpperCase()}</small><h3>${st.name}</h3><span class="micro">${done?'Selesai · boleh kunjungi lagi':open?'Siap dijelajahi':'Selesaikan tahap sebelumnya'}</span></a>`;}
function home(){
 const open=id=>unlocked(id,S,stages,CONFIG.sequential);
 return `${head(S.student?`Halo, ${esc(S.student.name)}!`:'Halo, Penjelajah!',S.mode==='serius'?'Pilih tahap untuk belajar pola bilangan bersama Si KOMA.':'Pilih tujuan di peta untuk belajar pola bilangan bersama Si KOMA.')}
 ${S.mode==='petualangan'?chartedMap(stages,S,open):`<div class="card"><h2>Daftar tahap belajar</h2><p>Ikuti urutan dari Bekal Penjelajah sampai Evaluasi.</p>${button('Lanjutkan belajar →','start')}</div>`}<p><a class="btn secondary" href="#lab">Laboratorium Pola · selalu tersedia</a> ${button('Ganti mode','mode-change','soft')}</p><p>${S.done.length} dari 8 tahap selesai · Poin motivasi ${Object.values(S.points||{}).reduce((a,b)=>a+b,0)} · Lencana ${(S.awards||[]).length}</p>${(S.awards||[]).length?`<div class="guide"><img src="assets/koma-praise.svg" alt="Si KOMA memberikan apresiasi" width="80"><div><strong>Terima kasih sudah tekun mencoba!</strong><p>${S.awards.map(a=>"🏅 "+esc(stages.find(s=>s.id===a.stage)?.name||a.stage)).join(" · ")}</p></div></div>`:""}<div class="section-title"><h2>Daftar tahap</h2><span class="micro">Boleh kunjungi lagi tahap yang selesai.</span></div>
 <div class="grid four">${stages.map(stageCard).join('')}</div>${S.records.a4?journalMarkup(S.records):''}`;
}
function material(){return `${head('Bekal penjelajah','Kenali pola, tonton contoh, lalu coba sendiri.')}${scene('lab')}<div class="tabs" role="tablist">${[['baca','▤ Baca & pahami'],['video','▷ Tonton'],['lab','⚗ Laboratorium pola']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" class="tab ${tab===id?'selected':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</div>${tab==='baca'?reading():tab==='video'?video():laboratory()}<div class="button-row" style="margin-top:25px">${button('Bekalku siap · lanjut aktivitas →','finish-material')}${button('Dengarkan petunjuk','speak','secondary')}</div>`;}
function reading(){return `<div class="grid two"><article class="card article"><span class="pill">01 · MEMBESAR</span><h2 style="margin-top:18px">Sedikit demi sedikit, bertambah.</h2><p>Pola bilangan mengikuti aturan tertentu. Di sini kita memakai perubahan yang <strong>tetap</strong>.</p>${nums([4,7,10,13],3)}<p>Dari 4 ke 7 bertambah 3. Dari 7 ke 10 juga bertambah 3. Jadi, bilangan selanjutnya adalah <strong>16</strong>.</p></article><article class="card article"><span class="pill">02 · MENGECIL</span><h2 style="margin-top:18px">Berkurang dengan jumlah yang sama.</h2>${nums([28,24,20,16],-4)}<p>Setiap bilangan berkurang 4. Jadi setelah 16 adalah <strong>12</strong>, karena 16 − 4 = 12.</p></article></div><div class="card" style="margin-top:20px"><h2>Bagaimana menemukan bilangan yang hilang?</h2>${nums([6,11,'?',21],5)}<p>Isi bagian kosong dengan <strong>16</strong>. Periksa kedua sisinya: 11 + 5 = 16 dan 16 + 5 = 21.</p><div class="guide">${iconKoma}<p>“Jangan hanya menulis tambah 5. Tunjukkan pasangan bilangan yang menjadi buktimu.”</p></div></div><details class="card" style="margin-top:20px"><summary><strong>Capaian dan tujuan pembelajaran</strong></summary><p style="margin-top:16px">Ringkasan CP Fase B, elemen Aljabar: mengenali, meniru, dan mengembangkan pola gambar atau benda serta pola bilangan membesar dan mengecil melalui penjumlahan dan pengurangan pada bilangan cacah sampai 100.</p><ul><li>Mengurai informasi dan mengajukan dugaan beserta dasarnya.</li><li>Menemukan dan menjelaskan perubahan tetap antarsuku.</li><li>Memberikan bukti yang mendukung aturan.</li><li>Menggunakan aturan pada posisi baru.</li><li>Menyusun langkah, memeriksa, dan menarik kesimpulan.</li></ul><p class="micro">Parafrasa CP relevan; acuan: Panduan Mata Pelajaran Matematika BSKAP 2025 dan Buku Panduan Guru Matematika kelas IV.</p></details>`;}
function video(){return `<div class="grid two"><div class="card"><div class="eyebrow">TONTON & AMATI</div><h2>Dua cara bilangan berubah</h2><p>Pilih contoh, amati dua perpindahan, lalu jeda untuk membuat dugaanmu.</p>${['membesar','mengecil'].map(kind=>`<h3>Pola ${kind}</h3><video controls preload="none" playsinline class="local-film" poster="assets/pola-${kind}.png" aria-label="Video contoh pola ${kind}"><source src="assets/pola-${kind}.mp4" type="video/mp4"></video><p class="micro">${kind==='membesar'?'3, 6, 9, … · Berapa tambahan pada setiap langkah?':'14, 11, 8, … · Berapa yang berkurang setiap langkah?'}</p>`).join('')}<details><summary>Pengayaan YouTube</summary><div id="video-slot" class="video-placeholder">${CONFIG.videos.filter(v=>v.id).map(v=>button('Putar '+esc(v.title),'load-video','secondary',`data-video="${esc(v.id)}"`)).join(' ')}</div><small>Sumber pengayaan: Lintang Berseri. Pemutar ini memerlukan internet.</small></details></div><form class="card" id="video-form"><h2>Setelah menonton</h2><label for="video-kind">Pola membesar atau mengecil?</label><input id="video-kind" name="kind" required maxlength="100" value="${esc(S.drafts.video?.kind||'')}"><label for="video-change">Berubah berapa setiap langkah?</label><input id="video-change" name="change" required maxlength="100" value="${esc(S.drafts.video?.change||'')}"><label for="video-proof">Apa buktinya?</label><textarea id="video-proof" name="proof" required maxlength="2000">${esc(S.drafts.video?.proof||'')}</textarea><p></p><button class="btn" type="submit">Simpan pengamatan</button></form></div>`;}
function laboratory(){return `<div class="card"><div class="page-head"><div><h2>Mesin Pola Si KOMA</h2><p>Atur mesinnya. Lihat perubahan pada benda dan bilangan.</p></div><span class="pill">COBA LANGSUNG</span></div><div class="controls ${lab.guess&&!lab.proved?'hidden':''}"><div><label for="lab-start">Bilangan awal</label><input id="lab-start" type="number" min="0" max="100" value="${lab.start}"></div><div><label for="lab-mode">Perubahan</label><select id="lab-mode"><option value="1" ${lab.step>0?'selected':''}>Tambah</option><option value="-1" ${lab.step<0?'selected':''}>Kurang</option></select></div><div><label for="lab-step">Sebanyak</label><input id="lab-step" type="number" min="1" max="10" value="${Math.abs(lab.step)}"></div><div><label for="lab-count">Banyak posisi</label><input id="lab-count" type="number" min="3" max="8" value="${lab.count}"></div></div><div class="button-row" style="margin-top:20px">${lab.guess&&!lab.proved?'':button('Terapkan','lab-apply')}${button('Satu langkah +','lab-step','secondary')}${button(labTimer?'Jeda':'Putar pelan','lab-play','secondary')}${button('Ulangi','lab-reset','soft')}${button('Mode tebak','lab-guess','soft')}${button('Jadikan pola pembanding','lab-compare','secondary')}</div><div id="lab-output" class="lab-output" aria-live="polite"></div><div class="grid two"><div><label for="lab-prediction">Dugaanku untuk bilangan berikutnya</label><input id="lab-prediction" type="number" min="0" max="100" value="${esc(lab.prediction)}"><label for="lab-reason">Aturan dan alasanku</label><textarea id="lab-reason" maxlength="2000" placeholder="Aku melihat … sehingga …">${esc(lab.reason)}</textarea></div><div class="guide">${iconKoma}<div><strong>Duga dulu, baru buktikan.</strong><p>Apakah jumlah tambahannya selalu sama? Bagaimana jika bilangan awal diganti?</p></div></div></div><div class="button-row" style="margin-top:18px">${button('Simpan dugaan & buktikan','lab-prove')}${button('Simpan pengamatan','lab-save','secondary')}</div><div id="lab-feedback" aria-live="polite"></div>${labBaseline?`<section class="card"><h3>Bandingkan kedua pola</h3><p>Pola tersimpan: ${labBaseline.join(", ")}</p><p>Pola sekarang: ${sequence(lab.start,lab.step,lab.count).slice(0,lab.guess&&!lab.proved?3:lab.count).join(", ")}</p><p>Apa yang sama? Apakah bilangan awal, perubahan, atau keduanya berbeda?</p></section>`:""}</div>`;}
function renderLab(){let a;try{a=sequence(lab.start,lab.step,lab.count);}catch(e){document.querySelector('#lab-output').textContent=e.message;return;}const shown=lab.guess&&!lab.proved?3:lab.shown;const visible=a.slice(0,shown);document.querySelector('#lab-output').innerHTML=`${nums(visible,lab.guess&&!lab.proved?undefined:lab.step)}<div class="grid two"><div>${visible.map((n,i)=>`<div class="pot-row"><span class="pot-label">Posisi ${i+1}<br><strong>${n}</strong></span><span class="objects">${Array.from({length:n},(_,j)=>`<i class="dot ${i&&lab.step>0&&j>=visible[i-1]?'extra':''}"></i>`).join('')}</span></div>`).join('')}</div><div><table class="mini-table"><thead><tr><th>Posisi</th><th>Bilangan</th></tr></thead><tbody>${visible.map((n,i)=>`<tr><td>${i+1}</td><td>${n}</td></tr>`).join('')}</tbody></table><p class="micro">Tiap kotak mewakili satu benda. Emas menandai benda tambahan.</p></div></div>${lab.guess&&!lab.proved?'<p class="micro">Aturan tersembunyi. Simpan dugaanmu untuk posisi keempat.</p>':''}`;}
function activities(){return `${head('Empat misi berpikir','Satu masalah, empat cara untuk memahaminya.')}<div class="grid two">${stages.slice(1,5).map((s,i)=>stageCard(s,i)).join('')}</div><div class="guide" style="margin-top:25px">${iconKoma}<p>Kita mulai dari dugaan. Setelah menemukan pola, kamu boleh memperbaiki dugaanmu. Itu bagian dari belajar!</p></div>`;}
const story='Si KOMA menata pot di taman. Baris pertama berisi 6 pot, baris kedua 10 pot, dan baris ketiga 14 pot. Banyaknya bertambah sama pada setiap baris. Berapa pot pada baris kelima?';
function pots(extra=false,color=false){return [6,10,14].map((n,i)=>`<div class="pot-row"><span class="pot-label">Baris ${i+1}<br><strong>${n} pot</strong></span><div class="objects" style="max-width:none;gap:8px">${Array.from({length:n},(_,j)=>`<i class="plant ${extra&&i&&j>=[6,10][i-1]?'extra':''}" ${color?`style="filter:hue-rotate(${j%3*65}deg)"`:''}></i>`).join('')}</div></div>`).join('');}
const algorithmItems=['Periksa setiap perubahan dan banyak baris.','Tulis 6 pot pada baris pertama.','Simpulkan banyak pot pada baris kelima.','Tambahkan 4 untuk setiap baris berikutnya sampai baris kelima.','Baca posisi yang ditanyakan.'];
function orderMarkup(items,order,namespace){return `<ol class="order-list">${order.map((idx,pos)=>`<li><span class="step-num">${pos+1}</span><span>${esc(items[idx])}</span><button type="button" data-action="move" data-ns="${namespace}" data-pos="${pos}" data-dir="-1" ${pos===0?'disabled':''} aria-label="Naikkan langkah ${pos+1}">↑</button><button type="button" data-action="move" data-ns="${namespace}" data-pos="${pos}" data-dir="1" ${pos===order.length-1?'disabled':''} aria-label="Turunkan langkah ${pos+1}">↓</button></li>`).join('')}</ol>`;}
function activity(i){const m=activityMeta[i],d=draft(),r=S.records[route],saved=!!r;
let content='';
if(i===0)content=`${pots()}<h3 class="step-heading">1. Apa yang diketahui?</h3><p class="micro">Pilih kelompok untuk setiap kartu.</p>${['Baris pertama berisi 6 pot','Baris kedua berisi 10 pot','Baris ketiga berisi 14 pot','Pertambahan tiap baris sama','Banyak pot pada baris kelima'].map((t,k)=>`<label for="sort${k}">${t}</label><select required id="sort${k}" name="sort${k}"><option value="">Pilih kelompok</option><option ${d['sort'+k]==='diketahui'?'selected':''} value="diketahui">Diketahui</option><option ${d['sort'+k]==='ditanyakan'?'selected':''} value="ditanyakan">Ditanyakan</option></select>`).join('')}<h3 class="step-heading">2. Apa yang ditanyakan?</h3>${textField('small','Pertanyaan kecil apa yang perlu dijawab?','Apa yang berubah? Bagaimana melanjutkan baris?')}<h3 class="step-heading">3. Sampaikan dugaan awal</h3>${textField('guess','Dugaan banyak pot pada baris kelima','Tulis perkiraanmu','number')}${textField('reason','Apa dasar dugaanmu?','Aku memperkirakan … karena …')}`;
if(i===1)content=`<h3 class="step-heading">1. Bandingkan setiap pasangan</h3><p>Pilih dua baris dan coba pasangkan pot satu per satu.</p>${pairingMarkup(d)}<div class="field-row"><div>${textField('diff1','10 − 6 =','Selisih','number')}</div><div>${textField('diff2','14 − 10 =','Selisih','number')}</div></div>${textField('relation','Apakah perubahan keduanya sama? Jelaskan.','Dari … ke … berubah …')}<h3 class="step-heading">2. Lanjutkan pola</h3><div class="field-row"><div>${textField('row4','Banyak pot baris keempat','','number')}</div><div>${textField('row5','Banyak pot baris kelima','','number')}</div></div><h3 class="step-heading">3. Detektif kesalahan</h3>${nums([6,10,15,18])}${textField('fix','Bilangan mana yang perlu diperbaiki agar selalu tambah 4? Mengapa?','Ganti … menjadi … karena …')}`;
if(i===2)content=`${pots(false,true)}<h3 class="step-heading">1. Pilih informasi yang diperlukan untuk mencari banyak pot</h3>${['Warna pot','Bentuk pot','Banyak pot awal','Perubahan setiap baris','Nomor baris yang dicari'].map((t,k)=>`<label class="check-label"><input type="checkbox" name="info${k}" ${d['info'+k]?'checked':''}>${t}</label>`).join('')}<h3 class="step-heading">2. Buat dan buktikan aturan</h3>${textField('rule','Tuliskan aturanmu','Mulai dari … lalu … setiap berpindah baris.')}${textField('proof','Mengapa aturanmu sesuai? Tunjukkan dua perpindahan.','… + … = … dan … + … = …')}<h3 class="step-heading">3. Gunakan pada posisi baru</h3>${textField('row6','Banyak pot pada baris keenam','','number')}${textField('transfer','Bagaimana aturanmu menghasilkan jumlah itu?','Aku melanjutkan …')}<h3 class="step-heading">4. Periksa batas aturanmu</h3>${textField('compare','Bandingkan dengan 9, 13, 17. Apa yang sama dan apa yang berbeda?','Awalnya … sedangkan perubahannya …')}`;
if(i===3){d.order??=[0,1,2,3,4];S.drafts[route]=d;content=`<h3>1. Susun langkahmu</h3><p class="micro">Gunakan tombol naik dan turun. Baca urutannya dari atas.</p>${orderMarkup(algorithmItems,d.order,'activity')}<div class="button-row">${button('Jalankan satu langkah','run-order','secondary','type="button"')}${button('Ulangi langkah','reset-order','soft','type="button"')}</div><div id="run-output" class="feedback">${esc(d.runText||'Langkah yang kamu jalankan akan muncul di sini.')}</div><h3 class="step-heading">2. Temukan kesalahan</h3><p>Si KOMA mulai dari 6, lalu menambah 4 sebanyak <strong>lima kali</strong> untuk mencari baris kelima.</p>${textField('debug','Apa yang harus diperbaiki? Mengapa?','Banyak penambahannya seharusnya …')}<h3 class="step-heading">3. Simpulkan</h3>${textField('conclusion','Apa jawaban untuk masalah taman? Sertakan satuan dan alasan.','Baris kelima membutuhkan … pot karena …')}${textField('reflection','Apakah dugaan awalmu berubah? Jelaskan.','Awalnya aku menduga … setelah memeriksa …')}`;}
const practice=['Persediaan pita: 32, 27, 22. Pengurangannya tetap. Apa yang diketahui dan ditanyakan jika mencari hari kelima? Tuliskan dugaanmu dan dasar perkiraannya.','Lanjutkan 35, 30, 25 dengan dua bilangan lagi. Jelaskan perubahan pada dua pasangan.','Pada 40, 34, 28, buat aturan dan buktikan dengan dua perpindahan. Gunakan aturan itu untuk posisi keenam.','Banyak baterai di pos 1 sampai 3: 50, 43, 36. Susun langkah mencari pos 6, jalankan, lalu tulis kesimpulan.'];if(i!==1)content+=`<details style="margin-top:24px"><summary><strong>Tantangan tambahan · pola mengecil</strong></summary><p style="margin-top:15px">${practice[i]}</p>${textField('decreasing','Jawaban dan alasan untuk pola mengecil','Tuliskan caramu di sini','textarea',false)}</details>`;
if(i===1)content+=`<h3 class="step-heading">4. Selidiki pola mengecil</h3><p>Amati persediaan pita di tiga hari pertama. Banyaknya berkurang tetap. Bandingkan dua perpindahan sebelum memperkirakan hari berikutnya.</p>${nums([35,30,25,'?','?'])}<div class="field-row"><div>${textField('down1','Dari 35 ke 30 berkurang berapa?','','number')}</div><div>${textField('down2','Dari 30 ke 25 berkurang berapa?','','number')}</div></div><div class="field-row"><div>${textField('down4','Banyak pita hari keempat','','number')}</div><div>${textField('down5','Banyak pita hari kelima','','number')}</div></div>${textField('downReason','Apa hubungan antarbilangan? Jelaskan memakai kedua pasangan.','Pada kedua perpindahan … sehingga …')}`;
 // Divide the existing tasks at their headings. Only the active step is shown.
 const boundary=content.search(/<h3(?: class="step-heading")?>[1-4]\./);
 const intro=content.slice(0,boundary);
 const chunks=content.slice(boundary).split(/(?=<h3(?: class="step-heading")?>[1-4]\.)/);
 if(i===0){
   const pos=chunks[0].indexOf('<label for="sort4">');
   if(pos>=0){
     const question=chunks[0].slice(pos);
     chunks[0]=chunks[0].slice(0,pos);
     chunks[1]=chunks[1].replace('</h3>', '</h3>'+question);
   }
 }
 const idx=Math.max(0,Math.min(Number(d.page)||0,chunks.length-1));
 const finalStep=idx===chunks.length-1;
 let visible=chunks[idx];
 if(idx===0&&intro)visible=visible.replace('</h3>','</h3>'+intro);
 if(i===1&&idx===1)visible+=bridgeMarkup(saved?(r.revisions.at(-1)?.data||r.initial.data):null);
 if(i===3&&idx===2&&S.records.a1){
   const original=S.records.a1.initial.data;
   visible=visible.replace('<label for="reflection">',`<div class="initial-note"><strong>Dugaan awalku</strong><p>${esc(original.guess)} pot · ${esc(original.reason)}</p></div><label for="reflection">`);
 }
 return `${head(m.title,m.goal,`MISI ${i+1} DARI 4`)}${scene(stops[i+1][3])}
 <div class="activity-layout"><div><div class="story">${story}</div>
 <form id="activity-form" class="card" data-id="${route}" data-step="${idx}" data-total="${chunks.length}">
 <div class="step-meter"><span>Langkah ${idx+1} dari ${chunks.length}</span><progress value="${idx+1}" max="${chunks.length}"></progress></div>
 ${narrative(i,idx)}${visible}<div class="button-row step-nav">${idx?button('← Sebelumnya','act-prev','secondary','type="button"'):''}
 <button class="btn" type="submit">${finalStep?(saved?'Simpan perbaikan ✓':'Simpan jawaban awal ✓'):'Langkah berikutnya →'}</button></div>
 <p class="save-note">Draf tersimpan di perangkat. Jawaban awal dicatat setelah seluruh langkah diselesaikan.</p></form>
 ${saved&&finalStep?activityFeedback(i):''}${saved&&i===1&&finalStep?bridgeMarkup(r.revisions.at(-1)?.data||r.initial.data,'decreasing'):''}
 ${saved&&i===3&&finalStep?journalMarkup(S.records):''}
 ${saved&&finalStep&&(i!==1||!needsDecrease(S))?`<div class="button-row step-nav">${button('Selesai memeriksa · lanjut →','finish-activity')}</div>`:''}</div>
 <aside class="card side-help">${iconKoma}<span class="eyebrow">${m.place}</span><h3>Ayo ceritakan caramu.</h3>
 <p>${i===1&&finalStep?'Bandingkan 35 ke 30 dan 30 ke 25. Berapa pita yang berkurang pada setiap perpindahan?':saved?esc(m.hint):'Perhatikan cerita taman, lalu tuliskan pemikiranmu sendiri.'}</p>
 ${button('Bantuan Si KOMA','activity-hint','soft small')}<details><summary class="micro">Untuk guru</summary><p class="micro">${m.ct} · ${m.indicator}.</p></details></aside></div>`;
}
function activityCorrect(i,d){if(i===0)return [0,1,2,3].every(k=>d['sort'+k]==='diketahui')&&d.sort4==='ditanyakan';if(i===1)return ['diff1','diff2','row4','row5','down1','down2','down4','down5'].every((k,j)=>Number(d[k])===[4,4,18,22,5,5,20,15][j]);if(i===2)return !d.info0&&!d.info1&&d.info2&&d.info3&&d.info4&&Number(d.row6)===26;return JSON.stringify(d.order)==='[4,1,3,0,2]';}
function activityPoints(r){const i=Number(route[1])-1;return activityCorrect(i,r.initial.data)?10:r.revisions[0]&&activityCorrect(i,r.revisions[0].data)?7:0;}
function narrative(i,j){const texts=[['Mari baca cerita taman. Pisahkan informasi yang sudah diberikan supaya kita tahu bekal untuk menyelesaikannya.','Gunakan informasi tadi untuk menentukan hal yang belum diketahui. Tuliskan pertanyaan kecil yang akan membantumu.','Sekarang buat dugaan berdasarkan data tiga baris awal. Ceritakan informasi yang mendukung dugaanmu.'],['Kita akan memeriksa dugaan pada aktivitas sebelumnya. Bandingkan baris pertama dengan kedua, lalu kedua dengan ketiga. Pola naik berarti banyak benda bertambah; pola turun berarti berkurang.','Gunakan perubahan yang baru kamu temukan untuk melanjutkan baris keempat dan kelima.','Periksa apakah perubahan yang sama berlaku di setiap pasangan. Jika berbeda, jelaskan bilangan yang perlu diperbaiki.','Sekarang bandingkan dengan persediaan pita yang menurun. Cari selisih dua pasangan dahulu, lalu lanjutkan polanya.'],['Kita sudah menemukan perubahan pot. Pilih informasi yang memengaruhi banyak pot; pisahkan dari warna atau bentuk.','Gunakan informasi penting tadi untuk menyusun aturan. Buktikan dengan sedikitnya dua perpindahan.','Terapkan aturan yang sama pada posisi baru. Jelaskan langkahmu agar orang lain dapat memeriksanya.','Uji batas aturanmu pada pola lain. Bandingkan bilangan awal dan perubahannya.'],['Gunakan aturan yang kamu buat untuk menyusun langkah. Jalankan urutannya agar terlihat apakah sudah masuk akal.','Periksa cara Si KOMA. Hubungkan banyak perpindahan dengan posisi awal dan tujuan.','Satukan hasil dan langkahmu menjadi kesimpulan. Bandingkan dengan dugaan awal pada aktivitas pertama.']];return `<div class="guide step-narrative"><img class="koma" src="assets/koma-${i===0?'think':i===1?'hint':i===2?'experiment':'read'}.svg" alt="Si KOMA"><p>${texts[i][j]||texts[i].at(-1)}</p></div>`;}
function activityFeedback(i){const r=S.records[route],last=r.revisions.at(-1)?.data||r.initial.data;let msg='';if(i===0){const good=[0,1,2,3].every(k=>last['sort'+k]==='diketahui')&&last.sort4==='ditanyakan';msg=good?'Informasi diketahui dan ditanyakan sudah terpisah.':'Periksa pengelompokan: data tiga baris awal dan pertambahan sama adalah diketahui. Baris kelima yang dicari.';msg+=' Dugaanmu tersimpan. Kita akan mengujinya pada misi berikutnya.';}if(i===1){msg=Number(last.diff1)===4&&Number(last.diff2)===4&&Number(last.row4)===18&&Number(last.row5)===22?'Selisih dan dua bilangan lanjutan sudah sesuai.':'Periksa lagi: 10 − 6 = 4, 14 − 10 = 4. Setelah 14, tambahkan 4 pada setiap baris.';}if(i===1&&downComplete(last)){msg+=' '+(Number(last.down1)===5&&Number(last.down2)===5&&Number(last.down4)===20&&Number(last.down5)===15?'Pola mengecil juga sesuai. Guru akan membaca alasanmu.':'Periksa pola kedua: 35 ke 30 dan 30 ke 25 sama-sama berkurang 5. Coba lanjutkan dengan aturan itu.');}if(i===2)msg=Number(last.row6)===26?'Hasil posisi keenam sesuai. Alasan dan aturanmu tersimpan untuk ditinjau guru.':'Periksa penerapan aturan tambah 4 hingga baris keenam. Aturan dan alasanmu tetap tersimpan untuk ditinjau guru.';if(i===3)msg='Urutan, perbaikan langkah, dan kesimpulanmu tersimpan untuk ditinjau guru. Pastikan baris pertama tidak dihitung sebagai langkah penambahan.';const attempts=1+r.revisions.length;const correct=activityCorrect(i,last);if(!correct&&attempts===1)msg='Bandingkan kembali informasi dan perubahan bilangannya. Gunakan Bantuan Si KOMA, lalu coba sekali lagi. Jawaban awalmu tetap dicatat.';return `<div class="feedback" role="status"><strong>Terima kasih sudah mencoba!</strong><br>${msg}<p class="micro" style="margin-top:10px">${r.revisions.length} perbaikan dicatat · kualitas alasan diperiksa guru. Poin objektif: ${activityPoints(r)}. Setelah dua kesempatan, revisi tetap boleh dilakukan tanpa menambah poin.</p></div>`;}
function quizPage(){const qz=S.quiz;if(qz.i>=quiz.length){const score=quiz.reduce((n,q,i)=>n+(qz.attempts[i]?.[0]?.correct?1:0),0);return `${head('Bintang untuk usahamu!','Kamu telah menyelesaikan tantangan pola.')}<div class="card quiz-shell"><div class="confetti">✦ ☆ ✦</div><div class="score"><span class="fraction"><span>${score}</span><span>8</span></span></div><p>Benar pada percobaan pertama: ${score}. Belum benar pada percobaan pertama: ${8-score}.</p><p>Poin kuis: ${S.points?.quiz||0}. Terpecahkan setelah bantuan: ${Object.values(qz.attempts).filter(a=>a.some(x=>x.correct)).length} dari 8.</p><p>Hasil setelah bantuan dicatat terpisah. Angka ini adalah hasil latihan, bukan nilai akhir penalaran.</p><label for="quiz-reflection">Pilih satu jawaban dan jelaskan alasanmu</label><textarea id="quiz-reflection" maxlength="2000">${esc(qz.reflection||'')}</textarea><div class="button-row" style="margin-top:20px">${button('Simpan refleksi & lanjut petualangan →','finish-quiz')}${button('Lihat pembahasan','quiz-review','secondary')}</div></div>`;}
const i=qz.i,q=quiz[i],attempts=qz.attempts[i]||[],last=attempts.at(-1),finished=last?.correct||attempts.length>=2;return `${head('Tantangan Bintang Pola','Tidak perlu terburu-buru. Perhatikan perubahan bilangannya.')}${scene('star')}<div class="quiz-shell card"><div class="quiz-top"><span class="pill">SOAL ${i+1} DARI 8</span><span class="micro">☆ ${Object.values(qz.attempts).filter(a=>a.some(x=>x.correct)).length} terpecahkan</span></div><div class="progress-line"><span style="width:${i/8*100}%"></span></div><h2 class="question-big">${q.q}</h2>${q.pattern?`<div class="math-display">${q.pattern}</div>`:''}${q.type==='order'?orderMarkup(q.items,qz.order,'quiz'):q.options.map((x,k)=>`<button class="option ${qz.selected===k?'selected':''}" data-action="quiz-select" data-index="${k}" ${finished?'disabled':''}><span class="letter">${'ABCD'[k]}</span>${x}</button>`).join('')}${last?`<div class="feedback ${last.correct?'':'warn'}" role="status"><strong>${last.correct?'Sesuai!':'Ayo periksa kembali.'}</strong><br>${finished?q.why:'Bandingkan bilangan yang bersebelahan, lalu pilih kembali. Kesempatan kedua masih ada.'}</div>`:''}<div class="button-row" style="margin-top:22px">${finished?button(i===7?'Lihat hasil →':'Soal berikutnya →','quiz-next'):button('Periksa jawaban','quiz-check')}</div></div>`;}
function game(){return `${head('Games · Petualangan Pulau Pola','Kumpulkan empat keping kunci. Nyalakan mercusuar dengan kesimpulanmu.')}<div class="button-row" style="margin-bottom:16px"><span class="pill">${S.game.done.filter(n=>n<4).length}/4 KEPING KUNCI</span>${button('Cara bermain','game-help','secondary small')}${button('Simpan & keluar','game-exit','soft small')}</div><div class="game-map-scroll"><div class="island-map game-landscape" tabindex="0" role="region" aria-label="Peta petualangan. Gunakan panah untuk bergerak, Enter untuk pos terdekat, atau klik tombol pos."><span class="map-water">PULAU POLA · LAUT IDE</span><div class="map-land"></div><div class="map-path"></div>${missions.map((m,i)=>`<button class="station ${S.game.done.includes(i)?'done':''}" data-action="mission" data-index="${i}" style="left:${m.x}%;top:${m.y}%" aria-label="Pos ${i+1}: ${m.title}">${S.game.done.includes(i)?'✓':m.icon}<small>${m.title}</small></button>`).join('')}<img class="player" src="assets/koma.svg" alt="Posisi Si KOMA"></div></div><div class="map-legend"><span><span class="keycap">↑ ↓ ← →</span> bergerak</span><span><span class="keycap">Enter</span> buka pos terdekat</span><span>Atau klik langsung nama pos</span></div><div class="button-row">${missions.map((m,i)=>`<button class="btn secondary small" data-action="mission" data-index="${i}">${i+1}. ${m.title}</button>`).join('')}</div><div id="mission-slot"></div>${S.game.done.length===5?`<div class="feedback"><h2>Mercusuar menyala! ✦</h2><p>Semua misi selesai. Penjelasanmu tersimpan untuk ditinjau guru.</p>${button('Lanjut ke evaluasi →','finish-game')}</div>`:''}`;}
function drawPlayer(){const el=document.querySelector('.player');if(el){el.style.left=S.game.x+'%';el.style.top=S.game.y+'%';}}
function openMission(i){if(i>0&&!S.game.done.includes(i-1)){toast('Kunjungi pos sebelumnya lebih dulu.');return;}activeMission=i;const m=missions[i];S.game.x=m.x;S.game.y=Math.min(90,m.y+15);save();drawPlayer();const prev=S.game.records[i]?.at(-1);const finished=S.game.done.includes(i);document.querySelector('#mission-slot').innerHTML=`<form id="mission-form" class="card mission-panel"><div class="eyebrow">POS ${i+1} · ${m.title}</div><h2>${m.q}</h2><label for="mission-answer">${m.key?'Jawaban akhir (angka)':'Hasil misi yang kamu pilih'}</label><input id="mission-answer" name="answer" required maxlength="200" value="${esc(prev?.answer||'')}" placeholder="${i===1?'Contoh format: 12, 17':'Tuliskan jawabanmu'}"><label for="mission-reason">${i===0?'Informasi diketahui, ditanyakan, dan dasar dugaanmu':i===3?'Tuliskan urutan langkah dan pemeriksaanmu':'Aturan, alasan, atau kesimpulanmu'}</label><textarea id="mission-reason" name="reason" required maxlength="2000">${esc(prev?.reason||'')}</textarea><div class="button-row" style="margin-top:18px"><button type="submit" class="btn" ${finished?'disabled':''}>${finished?'Misi telah selesai':'Periksa misi'}</button>${prev?button('Petunjuk','mission-hint','secondary','type="button"'):''}</div><div id="mission-feedback">${prev?`<div class="feedback">${prev.correct?'Hasil angka sesuai. ':''}${esc(finished?m.guide:m.hint)}<br>Penjelasan tersimpan untuk ditinjau guru.</div>`:''}</div></form>`;document.querySelector('#mission-slot').scrollIntoView({behavior:S.settings.motion?'smooth':'auto',block:'nearest'});}
function evaluationPage(){const e=S.evaluation;if(e.submission)return submitted();if(evalReview)return review();const i=e.i,a=e.answers[i];return `${head('Tunjukkan cara berpikirmu','Tuliskan jawaban dan alasan singkat dengan bahasamu sendiri.')}<div class="quiz-shell"><div class="q-dots">${evaluation.map((_,j)=>`<button data-action="eval-jump" data-index="${j}" class="q-dot ${e.answers[j].answer&&e.answers[j].reason?'filled':''} ${i===j?'active':''}" aria-label="Soal ${j+1}${e.answers[j].answer?' sudah diisi':''}">${j+1}</button>`).join('')}</div><form id="eval-form" class="card"><span class="pill">SOAL ${i+1} / 10</span><h2 class="question-big">${evaluation[i][1]}</h2><p class="micro">Semua pola memakai perubahan tetap. Jelaskan dalam 1–3 kalimat.</p><label for="eval-answer">Jawaban akhir</label><input id="eval-answer" name="answer" maxlength="300" value="${esc(a.answer)}" autocomplete="off"><label for="eval-reason">Alasan atau langkahku</label><textarea id="eval-reason" name="reason" maxlength="2500" placeholder="Aku menemukan … karena …">${esc(a.reason)}</textarea><p class="save-note">Draf disimpan di perangkat dan disinkronkan ke server. Periksa status penyimpanan di bawah halaman. Belum dikumpulkan.</p><div class="button-row">${i?button('← Sebelumnya','eval-prev','secondary','type="button"'):''}${button(i===9?'Tinjau jawaban →':'Berikutnya →','eval-next','','type="button"')}</div></form></div>`;}
function review(){return `${head('Periksa sebelum mengumpulkan','Jawaban awal akan dikunci setelah dikumpulkan.')}<div class="card quiz-shell">${evaluation.map((q,i)=>{const a=S.evaluation.answers[i];return `<div class="review-item"><strong>${i+1}. ${q[1]}</strong><p>${esc(a.answer||'(Jawaban masih kosong)')}<br>${esc(a.reason||'(Penjelasan masih kosong)')}</p><button class="btn soft small" data-action="eval-jump" data-index="${i}">Edit soal ${i+1}</button></div>`;}).join('')}<div class="button-row" style="margin-top:22px">${button('Kirim Evaluasi ke Guru','eval-submit')}${button('Unduh draf CSV','eval-draft-download','secondary')}</div><p class="save-note">Pengumpulan final hanya berhasil setelah server mengonfirmasi. Periksa semua jawaban sebelum mengirim.</p></div>`;}
function makePayload(){return {sessionId:S.sessionId,version:CONFIG.version,id:uuid(),createdAt:new Date().toISOString(),student:S.student,answers:evaluation.map((q,i)=>({indicator:q[0],question:q[1],...S.evaluation.answers[i]})),learning:{journal:journalData(S.records),activities:S.records,quiz:S.quiz,game:S.game.records,experiments:S.records.lab||[]}};}
function submitted(){const sub=S.evaluation.submission;return `${head('Terima kasih sudah berpikir!','Jawaban asli terkunci setelah diterima server.')}<div class="card"><img class="koma" src="assets/koma-praise.svg" alt="Si KOMA memberi apresiasi"><h2>${esc(S.student.name)}</h2><p>Pengumpulan diterima server pada ${new Date(sub.payload.createdAt).toLocaleString('id-ID')}.</p><p id="submission-status">${esc(sub.emailMessage||'Guru dapat membuka dan mencetak jawaban dari Ruang Guru.')}</p><p>Nilai penalaran diperiksa guru secara manual. Poin latihan tidak menjadi nilai evaluasi.</p>${button('Lihat jawaban asli','eval-view','secondary')} ${button('Coba kirim email ke guru','eval-retry','secondary')}<p><a class="btn soft" href="#beranda">Kembali ke beranda</a></p></div>`;}
function profile(){const d=CONFIG.developer;return `${head('Di balik KOMATIK','Dikembangkan untuk menemani murid memahami matematika.')}<article class="card profile"><div><img class="profile-photo" src="${esc(d.photo)}" alt="Foto ${esc(d.name)}"><p class="micro" style="margin-top:15px">Pengembang KOMATIK · ${esc(d.year)}</p></div><div><div class="eyebrow">PROFIL DEVELOPER</div><h1>${esc(d.name)}</h1><p>${esc(d.program)}<br>${esc(d.institution)}</p><dl><dt>Email</dt><dd><a href="mailto:${esc(d.email)}">${esc(d.email)}</a></dd><dt>WhatsApp</dt><dd>${esc(d.whatsapp)}</dd><dt>Pembimbing 1</dt><dd>${esc(d.supervisors[0])}</dd><dt>Pembimbing 2</dt><dd>${esc(d.supervisors[1])}</dd></dl><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><p>KOMATIK memadukan konten matematika interaktif dengan kegiatan berpikir komputasional untuk memfasilitasi penalaran matematis murid kelas IV SD.</p><a href="#beranda" class="btn secondary">← Kembali ke beranda</a></div></article>`;}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
function captureForm(form){const data=Object.fromEntries(new FormData(form));form.querySelectorAll('[type=checkbox]').forEach(x=>data[x.name]=x.checked);return data;}
function snapshotActivity(data){const id=route;const item={at:new Date().toISOString(),data:structuredClone(data)};S.records[id]??={initial:item,revisions:[],hints:[]};if(S.records[id].initial!==item)S.records[id].revisions.push(item);save();}
async function sendEvaluation(){try{const r=await api('email');S.evaluation.submission.emailMessage=r.sent?'Layanan email menerima laporan untuk dikirim ke guru.':r.message;toast(S.evaluation.submission.emailMessage);}catch(e){toast(e.message)}if(route==='evaluasi')render();}
function speak(){if(!S.settings.sound){toast('Aktifkan suara di Pengaturan terlebih dahulu.');return;}if(!('speechSynthesis' in window)){toast('Browser ini tidak menyediakan pembaca suara.');return;}speechSynthesis.cancel();const text=route==='evaluasi'?'Tuliskan jawaban dan alasanmu sendiri, lalu tinjau sebelum mengumpulkan.':document.querySelector('.side-help p,.guide p,.page-head p')?.textContent||'Ayo amati pola dan jelaskan alasanmu.';const utterance=new SpeechSynthesisUtterance(text);utterance.lang='id-ID';utterance.rate=.88;speechSynthesis.speak(utterance);}
window.addEventListener('hashchange',()=>{clearInterval(labTimer);labTimer=null;render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='music-volume')musicVolume(Number(t.value));if(t.closest('#activity-form')){const d=captureForm(t.closest('form'));S.drafts[route]={...draft(),...d};save();}if(t.closest('#eval-form')){S.evaluation.answers[S.evaluation.i]=captureForm(t.closest('form'));save();}if(t.id==='quiz-reflection'){S.quiz.reflection=t.value;save();}if(t.id==='lab-prediction')lab.prediction=t.value;if(t.id==='lab-reason')lab.reason=t.value;if(t.closest('#video-form')){S.drafts.video=captureForm(t.closest('form'));save();}if(t.hasAttribute('data-note')&&teacherData){teacherData.notes??=[];teacherData.notes[Number(t.dataset.note)]=t.value;}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id.startsWith('v5-'))return;e.preventDefault();
if(f.id==='activity-form'){
 if(!ensureStudent(route))return;
 const d={...draft(),...captureForm(f)};
 const step=Number(f.dataset.step), total=Number(f.dataset.total);
 if([...f.querySelectorAll('[required]')].some(x=>!x.value.trim())){toast('Tuliskan jawaban untuk langkah ini.');return;}
 if(route==='a3'&&step===0&&![0,1,2,3,4].some(k=>d['info'+k])){toast('Pilih informasi yang kamu perlukan.');return;}
 if(route==='a4'&&step===0&&(!d.ran||d.runIndex<5)){toast('Jalankan kelima langkahmu, lalu lanjutkan.');return;}
 const last=step===total-1;
 if(!last){d.page=step+1;S.drafts[route]=d;save();render();document.querySelector('#activity-form').scrollIntoView({block:'start'});return;}
 S.drafts[route]=d;
 snapshotActivity(d);try{await flush();render();toast('Jawaban diterima server. Periksa hasilmu sebelum melanjutkan.');}catch{toast(C.msg);}
}
if(f.id==='video-form'){if(!ensureStudent())return;S.drafts.video=captureForm(f);S.records.video??=[];S.records.video.push({at:new Date().toISOString(),data:S.drafts.video});save();toast('Pengamatan video tersimpan.');}
if(f.id==='mission-form'){if(!ensureStudent())return;const i=activeMission,m=missions[i],d=captureForm(f);if(S.game.done.includes(i))return;if(!d.answer.trim()||!d.reason.trim()){toast('Tuliskan jawaban dan alasanmu.');return;}const correct=m.key===null||normalize(d.answer)===normalize(m.key);S.game.records[i]??=[];S.game.records[i].push({...d,correct,at:new Date().toISOString()});const attempts=S.game.records[i].length;const canFinish=correct||attempts>=2;if(canFinish&&!S.game.done.includes(i))S.game.done.push(i);if(S.game.done.length===5)mark('game');save();try{await flush();}catch{toast(C.msg);return;}const feedback=`<div class="feedback ${correct?'':'warn'}"><strong>${correct?(m.key?'Hasil angka sesuai!':'Kesimpulan tersimpan.'):'Ayo periksa sekali lagi.'}</strong><br>${correct||attempts>=2?m.guide:m.hint}<br>Penjelasanmu tersimpan untuk ditinjau guru.${canFinish?'<p>Pos ini selesai. Kamu boleh melanjutkan.</p>':''}</div>`;document.querySelector('#mission-feedback').innerHTML=feedback;if(canFinish){const slot=document.querySelector('#mission-feedback');slot.innerHTML+=button(i===4?'Selesaikan petualangan →':'Kembali ke peta →',i===4?'finish-game':'map-return','soft','type="button"');}}
});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
if(a==='close'){dialog.close();return;}if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');return;}
if(a==='start'){const id=stages.find(s=>!S.done.includes(s.id))?.id||'materi';if(ensureStudent(id)){dialog.close();go(id)};return;}
if(a==='help')showModal(`<div class="eyebrow">TIGA LANGKAH MUDAH</div><h2>Siap menjelajah?</h2><div class="waypoint"><span class="tile-icon mint">1</span><p>Baca materi dan coba Mesin Pola.</p></div><div class="waypoint"><span class="tile-icon yellow">2</span><p>Kerjakan empat misi. Tulis jawaban dan alasanmu, lalu periksa.</p></div><div class="waypoint"><span class="tile-icon peach">3</span><p>Ikuti kuis dan games, kemudian tinjau evaluasi sebelum mengirim ke guru.</p></div><p style="margin-top:18px">Gunakan kartu akses dari guru. Pilih mode Petualangan atau Serius; progresnya sama. Laboratorium selalu tersedia. Latihan memberi dua kesempatan. Evaluasi final diperiksa guru. Saat kembali, masuk dengan kartu yang sama lalu pilih Lanjutkan Belajar.</p>${button('Mulai belajar →','start')}`);
if(a==='music'){musicToggle();render();return;}
if(a==='settings')showModal(`<h2>Nyaman untukmu</h2><div class="button-row">${button(S.settings.sound?'Suara: aktif':'Suara: nonaktif','toggle-sound','secondary')}${button(S.settings.motion?'Animasi: aktif':'Animasi: nonaktif','toggle-motion','secondary')}</div><p class="micro" style="margin-top:20px">Suara menggunakan pembaca bawaan browser. Tombol Dengarkan membacakan petunjuk. Gunakan Ctrl + untuk memperbesar tampilan.</p>${button('Dengarkan petunjuk','speak','soft')}`);
if(a==='toggle-sound'){S.settings.sound=!S.settings.sound;save();dialog.close();toast(S.settings.sound?'Suara diaktifkan.':'Suara dinonaktifkan.');}
if(a==='toggle-motion'){S.settings.motion=!S.settings.motion;save();dialog.close();render();}
if(a==='speak')speak();
if(a==='mode-change'){S.mode=null;C.state=S;render();return;}
if(a==='session')showModal(`<h2>Paspor penjelajah</h2><p>${esc(S.student.name)} · ${esc(S.student.code)} · ${esc(S.student.className)}</p><p>Gunakan kartu akses yang sama untuk melanjutkan pada perangkat lain. Simpan progres sebelum keluar.</p><button class="btn" data-v5="sync">Simpan sekarang</button> <button class="btn secondary" data-v5="logout">Keluar</button>`);
if(a==='tab'){tab=el.dataset.tab;if(labTimer){clearInterval(labTimer);labTimer=null;}render();}
if(a==='load-video'){const v=CONFIG.videos.find(v=>v.id===el.dataset.video)||CONFIG.videos[0];document.querySelector('#video-slot').outerHTML=`<iframe class="video-frame" title="${esc(v.title)}" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.id)}?rel=0" allow="fullscreen; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}
if(a==='finish-material'){if(ensureStudent()){mark('materi');try{await flush();go('a1');}catch{toast(C.msg);}}}
if(a==='lab-compare'){labBaseline=sequence(lab.start,lab.step,lab.count).slice(0,lab.guess&&!lab.proved?3:lab.count);render();}
if(a==='lab-apply'){try{const start=Number(document.querySelector('#lab-start').value),step=Number(document.querySelector('#lab-step').value)*Number(document.querySelector('#lab-mode').value),count=Number(document.querySelector('#lab-count').value);sequence(start,step,count);lab={...lab,start,step,count,shown:3,guess:false,proved:false};render();}catch(err){toast(err.message);}}
if(a==='lab-step'){if(lab.guess&&!lab.proved){toast('Simpan dugaan dan buktikan dahulu.');return;}lab.shown=Math.min(lab.count,lab.shown+1);renderLab();}
if(a==='lab-play'){if(lab.guess&&!lab.proved){toast('Simpan dugaan lebih dahulu.');return;}if(labTimer){clearInterval(labTimer);labTimer=null;el.textContent='Putar pelan';}else{el.textContent='Jeda';labTimer=setInterval(()=>{lab.shown=Math.min(lab.count,lab.shown+1);renderLab();if(lab.shown>=lab.count){clearInterval(labTimer);labTimer=null;el.textContent='Putar pelan';}},1200);}}
if(a==='lab-reset'){clearInterval(labTimer);labTimer=null;lab.shown=3;lab.proved=false;render();}
if(a==='lab-guess'){clearInterval(labTimer);labTimer=null;const options=[[8,4,6],[36,-5,6],[7,3,6],[48,-6,6]];const [start,step,count]=options[Math.floor(Math.random()*options.length)];lab={start,step,count,shown:3,guess:true,proved:false,prediction:'',reason:''};render();}
if(a==='lab-prove'||a==='lab-save'){if(!ensureStudent())return;if(!lab.reason.trim()){toast('Tuliskan aturan atau alasanmu terlebih dahulu.');return;}if(a==='lab-prove'&&lab.prediction===''){toast('Isi dugaan bilangan berikutnya.');return;}S.records.lab??=[];const target=lab.guess?3:lab.shown;const arr=sequence(lab.start,lab.step,lab.count);if(target>=arr.length&&a==='lab-prove'){toast('Semua posisi sudah terbuka. Ulangi percobaan dahulu.');return;}S.records.lab.push({at:new Date().toISOString(),...lab,targetPosition:target+1});save();if(a==='lab-prove'){lab.proved=true;lab.shown=Math.min(lab.count,target+1);render();document.querySelector('#lab-feedback').innerHTML=`<div class="feedback">Dugaanmu ${Number(lab.prediction)===arr[target]?'sesuai':'perlu diperiksa'}. Posisi ${target+1} adalah ${arr[target]}. Aturannya ${lab.step>0?'tambah':'kurang'} ${Math.abs(lab.step)}.</div>`;}else toast('Pengamatan tersimpan.');}
if(a==='activity-hint'){const d=draft();d.hintCount=(d.hintCount||0)+1;S.drafts[route]=d;const r=S.records[route];if(r)r.hints.push({at:new Date().toISOString(),type:'prompt'});save();toast(d.hintCount===1?'Baca lagi hal yang diketahui dan ditanyakan. Bandingkan dua bagian yang berdekatan.':activityMeta[Number(route[1])-1].hint);}
if(a==='act-prev'){const d=draft();d.page=Math.max(0,(d.page||0)-1);S.drafts[route]=d;save();render();}
if(a==='pair-tab'||a==='pair'){const d=draft();if(a==='pair-tab')d.pairTab=Number(el.dataset.index);else{d.paired??={};const k=d.pairTab===1?1:0;d.paired[k]=!d.paired[k];}S.drafts[route]=d;save();render();}
if(a==='finish-activity'){
 const rec=S.records[route];if(!rec||!unlocked(route,S,stages,CONFIG.sequential))return;
 if(route==='a2'&&needsDecrease(S)){toast('Simpan jawaban tantangan pola mengecil dahulu.');return;}
 mark(route);try{await flush();toast('Hebat, kamu menuntaskan aktivitas ini! Lencana usahamu tersimpan.');go(next(route));}catch{toast(C.msg);}}
if(a==='move'){const ns=el.dataset.ns,d=ns==='activity'?draft():S.quiz;if(ns==='quiz'&&(S.quiz.attempts[S.quiz.i]?.at(-1)?.correct||S.quiz.attempts[S.quiz.i]?.length>=2))return;let order=d.order;const p=Number(el.dataset.pos),q=p+Number(el.dataset.dir);if(q<0||q>=order.length)return;[order[p],order[q]]=[order[q],order[p]];if(ns==='activity'){d.ran=false;d.runIndex=0;d.runText='Urutan diubah. Jalankan kembali.';d.runValues=[];S.drafts[route]=d;}save();render();}
if(a==='run-order'){const d=draft();d.runIndex??=0;d.runValues??=[];const step=d.order[d.runIndex];let msg=algorithmItems[step]||'Semua langkah sudah dijalankan.';if(step===1)d.runValues=[6];if(step===3){if(!d.runValues.length)msg='Belum ada nilai awal. Letakkan langkah “Tulis 6” sebelum menambahkan.';else d.runValues=[6,10,14,18,22];}if(step===2&&d.runValues.length<5)msg='Kesimpulan belum didukung hasil sampai baris kelima. Periksa urutannya.';d.runIndex++;d.ran=true;d.runText=msg+(d.runValues.length?' Hasil sementara: '+d.runValues.join(', ')+'.':'');S.drafts[route]=d;save();document.querySelector('#run-output').textContent=d.runText;}
if(a==='reset-order'){const d=draft();d.runIndex=0;d.runValues=[];d.ran=false;d.runText='Jalankan kembali urutanmu.';save();render();}
if(a==='quiz-select'){S.quiz.selected=Number(el.dataset.index);save();render();}
if(a==='quiz-check'){if(!ensureStudent())return;const i=S.quiz.i,q=quiz[i];if(S.quiz.attempts[i]?.at(-1)?.correct||S.quiz.attempts[i]?.length>=2)return;if(q.type!=='order'&&typeof S.quiz.selected!=='number'){toast('Pilih jawabanmu dahulu.');return;}const response=q.type==='order'?[...S.quiz.order]:S.quiz.selected,correct=q.type==='order'?JSON.stringify(response)===JSON.stringify(q.answer):response===q.key;S.quiz.attempts[i]??=[];S.quiz.attempts[i].push({response,correct,at:new Date().toISOString()});save();try{await flush();render();}catch{toast(C.msg);}}
if(a==='quiz-next'){S.quiz.i++;delete S.quiz.selected;save();render();}
if(a==='finish-quiz'){mark('kuis');try{await flush();go('game');}catch{toast(C.msg);}}
if(a==='quiz-review')showModal(`<h2>Pembahasan kuis</h2>${quiz.map((q,i)=>`<p><strong>${i+1}.</strong> ${q.why}</p>`).join('')}`);
if(a==='mission')openMission(Number(el.dataset.index));
if(a==='mission-hint'){toast(missions[activeMission].hint);S.game.records[activeMission].at(-1).hintOpened=true;save();}
if(a==='map-return'){render();window.scrollTo({top:0,behavior:'smooth'});}
if(a==='game-help')showModal(`<h2>Jelajahi lima pos</h2><p>Klik pos untuk langsung bergerak, atau gunakan tombol panah di peta dan Enter pada pos terdekat.</p><p>Jawab pertanyaan dan jelaskan alasanmu. Jika belum tepat, baca petunjuk dan coba lagi. Tidak ada nyawa yang hilang.</p><p>Setelah empat keping terkumpul, tulis kesimpulan di mercusuar.</p>`);
if(a==='game-exit'){save();go('beranda');}
if(a==='finish-game'){if(S.game.done.length<5){toast('Selesaikan semua pos terlebih dahulu.');return;}mark('game');try{await flush();go('evaluasi');}catch{toast(C.msg);}}
if(a==='eval-jump'){evalReview=false;S.evaluation.i=Number(el.dataset.index);save();render();}
if(a==='eval-prev'){S.evaluation.i=Math.max(0,S.evaluation.i-1);save();render();}
if(a==='eval-next'){if(S.evaluation.i===9)evalReview=true;else S.evaluation.i++;save();render();}
if(a==='eval-submit'){if(!ensureStudent())return;const empty=S.evaluation.answers.map((x,i)=>!x.answer.trim()||!x.reason.trim()?i+1:null).filter(Boolean);if(!confirm(empty.length?`Nomor ${empty.join(', ')} belum lengkap. Tetap kumpulkan jawaban asli?`:'Kumpulkan jawaban asli? Setelah diterima server jawaban tidak dapat diubah.'))return;el.disabled=true;try{await flush();const r=await api('submit',{data:S,rev:C.rev});C.rev=r.rev;C.state=r.data;S=r.data;C.dirty=false;changed(S);await flush();render();await sendEvaluation();}catch(e){toast(e.message);el.disabled=false;}}
if(a==='eval-retry')await sendEvaluation();
if(a==='eval-download'||a==='eval-draft-download'){if(!S.student){ensureStudent();return;}const p=S.evaluation.submission?.payload||makePayload();download(`KOMATIK-evaluasi-${p.id}.csv`,evaluationCSV(p),'text/csv;charset=utf-8');}
if(a==='eval-json')download(`KOMATIK-laporan-${S.evaluation.submission.payload.id}.json`,JSON.stringify(S.evaluation.submission.payload,null,2));
if(a==='eval-view')showModal(`<h2>Jawaban awalmu</h2>${S.evaluation.submission.payload.answers.map((x,i)=>`<div class="review-item"><strong>${i+1}. ${esc(x.question)}</strong><p>${esc(x.answer)}<br>${esc(x.reason)}</p></div>`).join('')}`);
});
document.addEventListener('keydown',e=>{if(route!=='game'||!e.target.closest('.island-map')||e.target.closest('button'))return;const moves={ArrowLeft:[-3,0],ArrowRight:[3,0],ArrowUp:[0,-4],ArrowDown:[0,4]};if(moves[e.key]){e.preventDefault();const [x,y]=moves[e.key];S.game.x=Math.max(5,Math.min(95,S.game.x+x));S.game.y=Math.max(10,Math.min(90,S.game.y+y));drawPlayer();save();}if(e.key==='Enter'){e.preventDefault();let closest=0,best=Infinity;missions.forEach((m,i)=>{const d=Math.hypot(m.x-S.game.x,m.y-S.game.y);if(d<best){best=d;closest=i;}});if(best<24)openMission(closest);else toast('Dekati salah satu pos, atau klik langsung posnya.');}});
C.setState=data=>{S=data;};C.draw=render;C.notify=message=>{for(const el of document.querySelectorAll('.sync-strip'))el.outerHTML=syncHTML();if(message)toast(message);};
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main')?.focus();});
await boot();
